<?php
$root=dirname(__DIR__);
require_once $root.'/app/bootstrap.php';
require_once $root.'/app/MigrationService.php';
MigrationService::run();
require_once $root.'/app/AuthService.php';
require_once $root.'/app/MediaLibraryService.php';
AuthService::boot();
$admin=AuthService::requireAdmin();
$notice=null;$error=null;
$page=max(1,(int)($_GET['media_page']??$_POST['media_page']??1));$perPage=in_array((int)($_GET['per_page']??$_POST['per_page']??25),[25,50,100],true)?(int)($_GET['per_page']??$_POST['per_page']??25):25;

if($_SERVER['REQUEST_METHOD']==='POST'){
    try{
        AuthService::requireCsrf();
        $action=(string)($_POST['action']??'');
        if($action==='media_upload'){MediaLibraryService::upload($admin,$_POST,$_FILES['image']??[]);$notice='Media uploaded.';}
        elseif($action==='media_update'){MediaLibraryService::update($admin,(int)($_POST['media_id']??0),$_POST);$notice='Media details saved.';}
        elseif($action==='media_crop'){MediaLibraryService::cropResize($admin,(int)($_POST['media_id']??0),$_POST);$notice='Media crop and resize applied.';}
        elseif($action==='media_resize'){MediaLibraryService::resize($admin,(int)($_POST['media_id']??0),$_POST);$notice='Media resized.';}
        elseif($action==='media_thumbnail'){MediaLibraryService::regenerateThumbnail($admin,(int)($_POST['media_id']??0),$_POST);$notice='Thumbnail regenerated.';}
        elseif($action==='media_reset_thumbnail'){MediaLibraryService::resetThumbnail($admin,(int)($_POST['media_id']??0));$notice='Thumbnail position reset.';}
        elseif($action==='media_versions'){MediaLibraryService::regenerateVersions($admin,(int)($_POST['media_id']??0));$notice='Optional versions regenerated.';}
        elseif($action==='media_delete'){MediaLibraryService::delete($admin,(int)($_POST['media_id']??0));$notice='Media deleted.';}
        elseif($action==='media_settings'){MediaLibraryService::saveSettings($admin,$_POST);$notice='Media settings saved.';}
        elseif($action==='media_reset_all'){
            if(trim((string)($_POST['confirm_reset']??''))!=='RESET MEDIA')throw new RuntimeException('Type RESET MEDIA to clear all managed media.');
            MediaLibraryService::resetAll($admin);$notice='All managed media has been cleared.';
        }
    }catch(Throwable $e){$error=$e->getMessage();}
}

$settings=MediaLibraryService::settings();
$media=MediaLibraryService::page($admin,$page,$perPage);
$versions=MediaLibraryService::versionsByMediaIds($admin,array_map(static fn($item)=>(int)$item['media_id'],$media['items']));
$typeOptions=MediaLibraryService::TYPES;
$modeOptions=['LONGEST'=>'Longest side','WIDTH'=>'Width','HEIGHT'=>'Height'];
function media_csrf(): string{return '<input type="hidden" name="csrf_token" value="'.e(AuthService::csrfToken()).'">';}
function media_persist(int $page,int $perPage): string{return '<input type="hidden" name="media_page" value="'.$page.'"><input type="hidden" name="per_page" value="'.$perPage.'">';}
function media_url(int $mediaId,string $version=''): string{return 'theme-media.php?id='.$mediaId.($version!==''?'&version='.rawurlencode($version):'');}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Media Settings - Toinky</title><link rel="stylesheet" href="assets/toinky-theme.css"><link rel="stylesheet" href="assets/toinky-admin-shell.css"><link rel="stylesheet" href="assets/toinky-admin-workspace.css"><link rel="stylesheet" href="assets/toinky-responsive.css"><style>
