t span{padding:4px 7px;border:1px solid #d7d0c4;border-radius:999px;background:#fff;font-size:11px}.thumb-crop-picker{position:relative;max-width:100%;overflow:hidden;border:1px solid #d7d0c4;background:#fff}.thumb-crop-picker img{display:block;width:100%;height:auto}.thumb-crop-box{position:absolute;border:2px solid #b58e46;box-shadow:0 0 0 9999px rgba(28,36,43,.28);pointer-events:none}.pagination{display:flex;gap:6px;margin:16px 0}.pagination a{padding:7px 10px;border:1px solid #d7d0c4;background:#fff;color:#1c242b;text-decoration:none}.pagination a.active{background:#1c242b;color:#fff}.reset-panel{border-color:#fecaca;background:#fff7f7}@media(max-width:900px){.layout{grid-template-columns:1fr}.workspace-main{padding:16px}.grid,.grid.two,.compact-grid{grid-template-columns:1fr}}
</style></head><body><div class="layout admin-app"><?php require_once __DIR__.'/_workspace_sidebar.php';render_workspace_sidebar($admin,'media',false);?><main class="workspace-main"><header class="workspace-page-header"><div><h1>Media</h1><p>Signed in as <?=e($admin['display_name'])?></p></div></header>
<?php if($notice):?><div class="notice"><?=e($notice)?></div><?php endif;?><?php if($error):?><div class="error"><?=e($error)?></div><?php endif;?>

<section class="panel"><h2>Upload Processing</h2><form method="post" class="grid"><?=media_csrf()?><input type="hidden" name="action" value="media_settings">
<label class="field">Max upload MB<input type="number" min="1" max="50" name="max_upload_mb" value="<?=(int)$settings['max_upload_mb']?>"></label>
<label class="field">Master max pixels<input type="number" min="250" max="3840" name="master_max_px" value="<?=(int)$settings['master_max_px']?>"></label>
<label class="field">Thumbnail size<input type="number" min="64" max="600" name="thumbnail_size_px" value="<?=(int)$settings['thumbnail_size_px']?>"></label>
<label class="field">JPEG quality<input type="number" min="50" max="95" name="jpeg_quality" value="<?=(int)$settings['jpeg_quality']?>"></label>
<label class="field">PNG compression<input type="number" min="0" max="9" name="png_compression" value="<?=(int)$settings['png_compression']?>"></label>
<label class="field"><input type="checkbox" name="generate_medium" value="1" <?=$settings['generate_medium']?'checked':''?>> Generate medium</label>
<label class="field">Medium max<input type="number" min="80" max="1920" name="medium_max_px" value="<?=(int)$settings['medium_max_px']?>"></label>
<label class="field">Medium mode<select name="medium_mode"><?php foreach($modeOptions as$value=>$label):?><option value="<?=$value?>" <?=$settings['medium_mode']===$value?'selected':''?>><?=e($label)?></option><?php endforeach;?></select></label>
<label class="field"><input type="checkbox" name="generate_large" value="1" <?=$settings['generate_large']?'checked':''?>> Generate large</label>
<label class="field">Large max<input type="number" min="120" max="3840" name="large_max_px" value="<?=(int)$settings['large_max_px']?>"></label>
<label class="field">Large mode<select name="large_mode"><?php foreach($modeOptions as$value=>$label):?><option value="<?=$value?>" <?=$settings['large_mode']===$value?'selected':''?>><?=e($label)?></option><?php endforeach;?></select></label>
<div class="field"><button class="btn gold" type="submit">Save Settings</button></div>
</form><p class="muted">New uploads are saved only as processed files. Oversized originals are not kept.</p></section>

<section class="panel"><h2>Add Media</h2><form method="post" enctype="multipart/form-data" class="grid"><?=media_csrf()?><input type="hidden" name="action" value="media_upload">
<label class="field">Type<select name="media_type"><?php foreach($typeOptions as$type):?><option><?=e($type)?></option><?php endforeach;?></select></label>
<label class="field">Title<input name="title_text" maxlength="190" required></label>
<label class="field">Alternative text<input name="alt_text" maxlength="500" required></label>
<label class="field">Image<input type="file" name="image" accept="image/jpeg,image/png,image/webp" required></label>
<div class="field"><button class="btn gold" type="submit">Upload</button></div>
</form></section>

<section class="panel"><h2>Media Library</h2><p class="muted"><?=(int)$media['total']?> active item<?=(int)$media['total']===1?'':'s'?>. Parallax hero and Story Artwork uploads use this same library.</p>
<?php if(!$media['items']):?><p>No media has been uploaded yet.</p><?php endif;?>
<div class="media-grid"><?php foreach($media['items'] as$item):$itemVersions=$versions[(int)$item['media_id']]??[];$mediaId=(int)$item['media_id'];?>
<article class="media-card"><img src="<?=e(media_url($mediaId,'THUMBNAIL'))?>" alt="<?=e($item['alt_text'])?>"><div class="media-card-body"><h3><?=e($item['title_text'])?></h3><p class="media-meta"><?=e($item['media_type'])?> | <?=(int)$item['width_px']?>x<?=(int)$item['height_px']?> | <?=number_format(((int)$item['file_size_bytes'])/1024,1)?> KB</p>
<div class="version-list"><?php foreach(['THUMBNAIL','MEDIUM','LARGE']as$code):?><span><?=$code?>: <?=isset($itemVersions[$code])?(int)$itemVersions[$code]['width_px'].'x'.(int)$itemVersions[$code]['height_px']:'none'?></span><?php endforeach;?></div>
<details><summary>Edit details</summary><form method="post" class="compact-grid"><?=media_csrf()?><?=media_persist((int)$media['page'],(int)$media['per_page'])?><input type="hidden" name="action" value="media_update"><input type="hidden" name="media_id" value="<?=(int)$item['media_id']?>">
<label class="field">Type<select name="media_type"><?php foreach($typeOptions as$type):?><option <?=$item['media_type']===$type?'selected':''?>><?=e($type)?></option><?php endforeach;?></select></label><label class="field">Title<input name="title_text" value="<?=e($item['title_text'])?>" maxlength="190" required></label><label class="field">Alternative text<input name="alt_text" value="<?=e($item['alt_text'])?>" maxlength="500" required></label><div class="field"><button class="btn" type="submit">Save</button></div></form></details>
<details><summary>Resize by scale or pixels</summary><form method="post" class="compact-grid"><?=media_csrf()?><?=media_persist((int)$media['page'],(int)$media['per_page'])?><input type="hidden" name="action" value="media_resize"><input type="hidden" name="media_id" value="<?=(int)$item['media_id']?>">
<label class="field">Mode<select name="resize_mode"><option value="pixels">Pixels</option><option value="scale">Scale percent</option></select></label><label class="field">Scale percent<input type="number" min="1" max="400" name="scale_percent" value="100"></label><label class="field">Width<input type="number" min="1" max="<?=(int)$settings['master_max_px']?>" name="resize_width"></label><label class="field">Height<input type="number" min="1" max="<?=(int)$settings['master_max_px']?>" name="resize_height"></label><div class="field"><button class="btn" type="submit">Resize</button></div></form></details>
<details><summary>Crop or resize</summary><form method="post" class="compact-grid"><?=media_csrf()?><?=media_persist((int)$media['page'],(int)$media['per_page'])?><input type="hidden" name="action" value="media_crop"><input type="hidden" name="media_id" value="<?=(int)$item['media_id']?>">
<label class="field">Crop X<input type="number" min="0" name="crop_x" value="0"></label><label class="field">Crop Y<input type="number" min="0" name="crop_y" value="0"></label><label class="field">Crop width<input type="number" min="1" max="<?=(int)$item['width_px']?>" name="crop_width" value="<?=(int)$item['width_px']?>"></label><label class="field">Crop height<input type="number" min="1" max="<?=(int)$item['height_px']?>" name="crop_height" value="<?=(int)$item['height_px']?>"></label><label class="field">Resize width<input type="number" min="1" max="<?=(int)$settings['master_max_px']?>" name="resize_width"></label><label class="field">Resize height<input type="number" min="1" max="<?=(int)$settings['master_max_px']?>" name="resize_height"></label><div class="field"><button class="btn" type="submit">Apply</button></div></form></details>
<details><summary>Thumbnail crop</summary><form method="post" class="compact-grid" data-thumb-form data-image-width="<?=(int)$item['width_px']?>" data-image-height="<?=(int)$item['height_px']?>"><?=media_csrf()?><?=media_persist((int)$media['page'],(int)$media['per_page'])?><input type="hidden" name="action" value="media_thumbnail"><input type="hidden" name="media_id" value="<?=(int)$item['media_id']?>"><div class="thumb-crop-picker" data-thumb-picker><img src="<?=e(media_url($mediaId,'MEDIUM'))?>" alt=""><span class="thumb-crop-box" data-thumb-box></span></div><label class="field">Crop X<input type="number" min="0" max="<?=(int)$item['width_px']-1?>" name="thumbnail_crop_x" value="<?=(int)($item['thumbnail_crop_x']??0)?>"></label><label class="field">Crop Y<input type="number" min="0" max="<?=(int)$item['height_px']-1?>" name="thumbnail_crop_y" value="<?=(int)($item['thumbnail_crop_y']??0)?>"></label><label class="field">Square size<input type="number" min="1" max="<?=min((int)$item['width_px'],(int)$item['height_px'])?>" name="thumbnail_crop_size" value="<?=(int)($item['thumbnail_crop_size']??min((int)$item['width_px'],(int)$item['height_px']))?>"></label><div class="field"><button class="btn" type="submit">Save Thumb</button></div></form><form method="post" class="actions"><?=media_csrf()?><?=media_persist((int)$media['page'],(int)$media['per_page'])?><input type="hidden" name="action" value="media_reset_thumbnail"><input type="hidden" name="media_id" value="<?=(int)$item['media_id']?>"><button class="btn alt" type="submit">Reset</button></form></details>
<div class="actions"><form method="post"><?=media_csrf()?><?=media_persist((int)$media['page'],(int)$media['per_page'])?><input type="hidden" name="action" value="media_versions"><input type="hidden" name="media_id" value="<?=(int)$item['media_id']?>"><button class="btn alt" type="submit">Regenerate Versions</button></form><form method="post" onsubmit="return confirm('Delete this media item and detach it everywhere?')"><?=media_csrf()?><?=media_persist((int)$media['page'],(int)$media['per_page'])?><input type="hidden" name="action" value="media_delete"><input type="hidden" name="media_id" value="<?=(int)$item['media_id']?>"><button class="btn alt danger" type="submit">Delete</button></form></div>
</div></article><?php endforeach;?></div>
<?php if((int)$media['pages']>1):?><nav class="pagination" aria-label="Media pages"><?php for($pageNo=1;$pageNo<=(int)$media['pages'];$pageNo++):?><a class="<?=$pageNo===(int)$media['page']?'active':''?>" href="?media_page=<?=$pageNo?>&per_page=<?=(int)$media['per_page']?>"><?=$pageNo?></a><?php endfor;?></nav><?php endif;?></section>

<section class="panel reset-panel"><h2>Reset Media Library</h2><p>This removes all managed media records and files, including story artwork attachments and media library uploads. It does not remove built-in assets.</p><form method="post" class="grid two"><?=media_csrf()?><input type="hidden" name="action" value="media_reset_all"><label class="field">Type RESET MEDIA<input name="confirm_reset" autocomplete="off"></label><div class="field"><button class="btn alt danger" type="submit">Clear All Media</button></div></form></section>
</main></div><script>
document.querySelectorAll('[data-thumb-form]').forEach(form=>{const picker=form.querySelector('[data-thumb-picker]'),image=picker?.querySelector('img'),box=picker?.querySelector('[data-thumb-box]'),xInput=form.elements.thumbnail_crop_x,yInput=form.elements.thumbnail_crop_y,sizeInput=form.elements.thumbnail_crop_size,width=Number(form.dataset.imageWidth),height=Number(form.dataset.imageHeight);if(!picker||!image||!box)return;const render=()=>{const scale=image.clientWidth/width,size=Math.min(Number(sizeInput.value)||1,width,height),x=Math.max(0,Math.min(Number(xInput.value)||0,width-size)),y=Math.max(0,Math.min(Number(yInput.value)||0,height-size));xInput.value=Math.round(x);yInput.value=Math.round(y);box.style.left=(x*scale)+'px';box.style.top=(y*scale)+'px';box.style.width=(size*scale)+'px';box.style.height=(size*scale)+'px';};picker.addEventListener('click',event=>{const rect=image.getBoundingClientRect(),scale=width/rect.width,size=Math.min(Number(sizeInput.value)||1,width,height),centerX=(event.clientX-rect.left)*scale,centerY=(event.clientY-rect.top)*scale;xInput.value=Math.round(Math.max(0,Math.min(centerX-size/2,width-size)));yInput.value=Math.round(Math.max(0,Math.min(centerY-size/2,height-size)));render();});[xInput,yInput,sizeInput].forEach(input=>input.addEventListener('input',render));image.addEventListener('load',render);window.addEventListener('resize',render);render();});
</script></body></html>
